routes.script:
LET $exists = QUERY SELECT id FROM {{t:main}} WHERE username = {{body.username}} LIMIT 1;
IF LEN($exists.rows) > 0
  RETURN 409 { "ok": false, "error": "USER_EXISTS" };
END
EXEC INSERT INTO {{t:main}} (only_id, username, password_hash, nickname, phone) VALUES ({{onlyId}}, {{body.username}}, SM4_ENC({{body.password}}, 'clickbuild-key'), {{body.nickname}}, {{body.phone}});
LET $t = TOKEN NEW { "onlyId": {{onlyId}}, "username": {{body.username}}, "role": "user" };
RETURN 201 { "ok": true, "onlyId": {{onlyId}}, "token": $t.token };

LET $u = QUERY SELECT only_id, password_hash, role FROM {{t:main}} WHERE username = {{body.username}} LIMIT 1;
IF LEN($u.rows) == 0
  RETURN 401 { "ok": false, "error": "NO_USER" };
END
IF SM4_DEC($u.rows[0].password_hash, 'clickbuild-key') != {{body.password}}
  RETURN 401 { "ok": false, "error": "BAD_PASSWORD" };
END
LET $t = TOKEN NEW { "onlyId": $u.rows[0].only_id, "username": {{body.username}}, "role": $u.rows[0].role };
RETURN 200 { "ok": true, "token": $t.token };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $row = QUERY SELECT {{allColumns:main}} FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($row.rows) == 0
  RETURN 404 { "ok": false, "error": "NOT_FOUND" };
END
RETURN 200 { "row": $row.rows[0] };

# 文件已经由服务器写进对象存储，这里只做入库；{{objectKey}} {{objectUrl}} {{filename}} {{size}} 都是现成的
EXEC UPDATE {{t:main}} SET {{bindColumn:main}} = {{objectKey}} WHERE {{idColumn:main}} = {{id}};
RETURN 200 { "key": {{objectKey}}, "url": {{objectUrl}}, "name": {{filename}} };

LET $p = QUERY SELECT stock FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($p.rows) == 0
  RETURN 404 { "ok": false, "error": "NO_PRODUCT" };
END
IF $p.rows[0].stock < {{body.qty}}
  RETURN 409 { "ok": false, "error": "OUT_OF_STOCK", "stock": $p.rows[0].stock };
END
EXEC UPDATE {{t:main}} SET stock = stock - {{body.qty}}, sales = sales + {{body.qty}} WHERE {{idColumn:main}} = {{id}} AND stock >= {{body.qty}};
RETURN 200 { "ok": true };

LET $c = QUERY SELECT id, qty FROM {{t:main}} WHERE user_only_id = {{user.onlyId}} AND product_id = {{body.product_id}} LIMIT 1;
IF LEN($c.rows) > 0
  EXEC UPDATE {{t:main}} SET qty = qty + {{body.qty}} WHERE id = $c.rows[0].id;
ELSE
  EXEC INSERT INTO {{t:main}} (user_only_id, product_id, qty) VALUES ({{user.onlyId}}, {{body.product_id}}, {{body.qty}});
END
RETURN 200 { "ok": true };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $row = QUERY SELECT {{allColumns:main}} FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($row.rows) == 0
  RETURN 404 { "ok": false, "error": "NOT_FOUND" };
END
RETURN 200 { "row": $row.rows[0] };

LET $ins = EXEC INSERT INTO {{t:main}} (order_no, user_only_id, receiver, address, amount) VALUES ({{body.order_no}}, {{onlyId}}, {{body.receiver}}, {{body.address}}, {{body.amount}});
LET $oid = QUERY SELECT LAST_INSERT_ID() AS id;
FOREACH $i IN {{body.items}}
  EXEC INSERT INTO {{t:item}} (order_id, product_id, title, qty, price) VALUES ({{vars.oid.rows.0.id}}, $i.product_id, $i.title, $i.qty, $i.price);
END
RETURN 201 { "ok": true, "id": $ins.insertId };

